    def boundary_sweep(pts):
        # Deterministic edge-snapping: try moving each point onto each edge
        # at a few positions; keep strictly improving moves. Helps escape
        # interior local optima by pushing points onto the boundary.
        cur = project(np.array(pts, dtype=float))
        curA = min_area(cur)
        edges = [(V[0], V[1]), (V[1], V[2]), (V[2], V[0])]
        for j in range(n):
            for (P, Q) in edges:
                for u in (0.15, 0.3, 0.5, 0.7, 0.85):
                    cand = cur.copy()
                    cand[j] = P + u * (Q - P)
                    mA = min_area(cand)
                    if mA > curA + 1e-15:
                        cur, curA = cand, mA
        return cur, curA

